description:
Implement a `highlight` tagged template literal function that wraps each interpolated value in `<mark>` tags, concatenated with the surrounding string parts.

**Example:**
```js
const name = 'Alice';
const age = 30;
highlight`Hello ${name}, you are ${age} years old!`;
// 'Hello <mark>Alice</mark>, you are <mark>30</mark> years old!'
```

starter_code:
export function highlight(strings, ...values) {
  // your code here
}

test_suite:
test('wraps interpolated values in mark tags', () => {
  const name = 'Alice';
  const result = highlight`Hello ${name}!`;
  expect(result).toBe('Hello <mark>Alice</mark>!');
});

test('handles multiple interpolations', () => {
  const a = 'foo';
  const b = 'bar';
  const result = highlight`${a} and ${b}`;
  expect(result).toBe('<mark>foo</mark> and <mark>bar</mark>');
});

test('no interpolations returns plain string', () => {
  const result = highlight`just text`;
  expect(result).toBe('just text');
});

// __hidden__
test('numeric values are stringified inside mark', () => {
  const n = 42;
  const result = highlight`value is ${n}`;
  expect(result).toBe('value is <mark>42</mark>');
});

solution:
export function highlight(strings, ...values) {
  return strings.reduce((acc, str, i) => {
    const val = values[i] !== undefined ? `<mark>${values[i]}</mark>` : '';
    return acc + str + val;
  }, '');
}
